package hidden

import (
	"testing"

	"example.com/expr/eval"
	"example.com/expr/lexer"
	"example.com/expr/parser"
)

func run(t *testing.T, s string) (int, error) {
	t.Helper()
	toks, err := lexer.Tokens(s)
	if err != nil {
		return 0, err
	}
	n, err := parser.Parse(toks)
	if err != nil {
		return 0, err
	}
	return eval.Eval(n)
}

func TestTokens(t *testing.T) {
	toks, err := lexer.Tokens(" 1 + 23*(4)")
	if err != nil {
		t.Fatal(err)
	}
	wantKind := []string{"num", "op", "num", "op", "lparen", "num", "rparen"}
	wantText := []string{"1", "+", "23", "*", "(", "4", ")"}
	if len(toks) != len(wantKind) {
		t.Fatalf("got %d tokens: %+v", len(toks), toks)
	}
	for i := range toks {
		if toks[i].Kind != wantKind[i] || toks[i].Text != wantText[i] {
			t.Errorf("token %d = %+v, want %s %q", i, toks[i], wantKind[i], wantText[i])
		}
	}
	if got, err := lexer.Tokens(""); err != nil || len(got) != 0 {
		t.Errorf("empty input = %v, %v", got, err)
	}
	if _, err := lexer.Tokens("1 $ 2"); err == nil {
		t.Error("an unknown character must be an error")
	}
}

func TestPrecedenceAndAssociativity(t *testing.T) {
	for _, c := range []struct {
		in   string
		want int
	}{
		{"1", 1},
		{"1+2*3", 7},
		{"2*(3+4)", 14},
		{"10-2-3", 5},
		{"100/5/2", 10},
		{"8/3", 2},
		{"(1+2)*(3+4)", 21},
		{" 7 * 6 ", 42},
		{"((5))", 5},
	} {
		got, err := run(t, c.in)
		if err != nil || got != c.want {
			t.Errorf("%q = %d, %v; want %d", c.in, got, err, c.want)
		}
	}
}

func TestErrors(t *testing.T) {
	for _, in := range []string{"1 +", "(1+2", "1 2", "*3", "1+2)"} {
		if _, err := run(t, in); err == nil {
			t.Errorf("%q must be an error", in)
		}
	}
	if _, err := run(t, "1/0"); err == nil {
		t.Error("division by zero must be an error")
	}
}
HIDDEN_EOF
go vet ./... || fail 'go vet'
go test ./... >/dev/null 2>&1 || fail 'go test'
go build -o .expr . || fail 'go build'
out=$(./.expr '2*(3+4)' 2>&1) || fail "the command failed: $out"
test "$out" = 14 || fail "the command printed $out, want 14"
out=$(./.expr '1/0' 2>&1); rc=$?
test "$rc" != 0 || fail 'the command on 1/0 must exit non-zero'
exit 0
